shader_body
{
    // drift the picture outward, a little more on the bass
    float2 d = (uv - 0.5) * (0.99 - q2);
    ret = tex2D(sampler_main, d + 0.5).xyz * 0.98;
    ret += 0.02 * (GetBlur1(uv) - ret);
}

