shader_body { 
 vec3 ret_1;
 ret_1 = (texture (sampler_main, ((
   (uv - 0.5)
  * 
   (0.99 - q2)
 ) + 0.5)).xyz * 0.98);
 ret_1 = (ret_1 + (0.02 * (
   ((texture (sampler_blur1, uv).xyz * scale1) + bias1)
  - ret_1)));
 vec4 tmpvar_2;
 tmpvar_2.w = 1.0;
 tmpvar_2.xyz = ret_1;
