shader_body
{
    float3 c = GetPixel(uv) + 0.4*GetBlur1(uv);
    float l = lum(c);
    ret = lerp(c, l * hue_shader, q1);
}

comp.glsl:
shader_body { 
 vec3 tmpvar_1;
 tmpvar_1 = (texture (sampler_main, uv).xyz + (0.4 * (
   (texture (sampler_blur1, uv).xyz * scale1)
  + bias1)));
 vec4 tmpvar_2;
 tmpvar_2.w = 1.0;
 tmpvar_2.xyz = mix (tmpvar_1, (dot (tmpvar_1, vec3(0.32, 0.49, 0.29)) * hue_shader), vec3(q1));
 ret = tmpvar_2.xyz;
}

warp.source:
float2 swirl(float2 p, float a)
{
    float s = sin(a), c = cos(a);
    return float2(p.x*c - p.y*s, p.x*s + p.y*c);
}

shader_body
{
    float2 p = swirl(uv - 0.5, 0.01*rad) + 0.5;
    float3 n = tex2D(sampler_noise_lq, uv*4 + q3).xyz - 0.5;
    ret = tex2D(sampler_fw_main, p + n.xy*0.002).xyz - 0.004;
}

warp.glsl:
shader_body { 
 vec2 p_1;
 p_1 = (uv - 0.5);
 float a_2;
 a_2 = (0.01 * rad);
 float tmpvar_3;
 tmpvar_3 = sin(a_2);
 float tmpvar_4;
 tmpvar_4 = cos(a_2);
 vec2 tmpvar_5;
 tmpvar_5.x = ((p_1.x * tmpvar_4) - (p_1.y * tmpvar_3));
 tmpvar_5.y = ((p_1.x * tmpvar_3) + (p_1.y * tmpvar_4));
 vec4 tmpvar_6;
 tmpvar_6.w = 1.0;
 tmpvar_6.xyz = (texture (sampler_fw_main, ((tmpvar_5 + 0.5) + (
   (texture (sampler_noise_lq, ((uv * 4.0) + q3)).xyz - 0.5)
 .xy * 0.002))).xyz - 0.004);
 ret = tmpvar_6.xyz;
}

comp.source:
shader_body
{
    float3 acc = 0;
    for (int i = 0; i < 4; i++) {
        float3 p = float3(uv*2, q3 + i*0.25);
        acc += tex3D(sampler_noisevol_lq, p).xyz / 4;
    }
    ret = GetMain(uv) + acc*0.1;
}

